// ============================================================
// localStorage polyfill for Node.js test environment
// ============================================================

if (!(globalThis as Record<string, unknown>).localStorage) {
  const store = new Map<string, string>();
  const ls = {
    getItem(key: string): string | null { return store.get(key) ?? null; },
    setItem(key: string, value: string): void { store.set(key, value); },
    removeItem(key: string): void { store.delete(key); },
    get length(): number { return store.size; },
    clear(): void { store.clear(); },
    key(index: number): string | null {
      const keys = Array.from(store.keys());
      return keys[index] ?? null;
    },
  };
  (globalThis as Record<string, unknown>).localStorage = ls;
  (globalThis as Record<string, unknown>).window = { localStorage: ls };
}

// ============================================================
// Polyfill Worker for Node.js test environment
// ============================================================

// In Node.js, there's no native Web Worker. We polyfill with a
// mock that forwards messages to a handler function, simulating
// the Worker API enough for TrainingRuntime to work.
class MockWorker implements Worker {
  onmessage: ((this: Worker, ev: MessageEvent) => unknown) | null = null;
  onerror: ((this: AbstractWorker, ev: ErrorEvent) => unknown) | null = null;
  onmessageerror: ((this: Worker, ev: MessageEvent) => unknown) | null = null;

  private _pendingMessages: Array<{ cmd: unknown; resolve: (msg: unknown) => void }> = [];

  postMessage(message: unknown): void {
    // Find the matching pending message handler
    const pending = this._pendingMessages.shift();
    if (pending) {
      pending.resolve(message);
    }
  }

  terminate(): void {
    this._pendingMessages = [];
  }

  addEventListener(): void { /* no-op */ }
  removeEventListener(): void { /* no-op */ }
  dispatchEvent(): boolean { return true; }

  // Test helper: queue a response from the "worker"
  _queueResponse(cmd: unknown, response: unknown): void {
    this._pendingMessages.push({ cmd, resolve: () => {
      if (this.onmessage) {
        this.onmessage.call(
          this as unknown as Worker,
          new MessageEvent("message", { data: response })
        );
      }
    }});
  }

  // Test helper: trigger error
  _triggerError(message: string): void {
    if (this.onerror) {
      this.onerror.call(
        this as unknown as Worker,
        new ErrorEvent("error", { message })
      );
    }
  }
}

// Install the mock Worker globally
const OriginalWorker = (globalThis as Record<string, unknown>).Worker;
(globalThis as Record<string, unknown>).Worker = MockWorker;

