function makeExperiment(seed: number): ResearchExperiment {
  return createResearchExperiment({
    name: `Phase65 Test (seed=${seed})`,
    description: "Real training test",
    modelConfig: {
      name: "tiny",
      label: "Phase65 Tiny",
      description: "",
      vocabSize: 1000,
      dModel: 64,
      numHeads: 4,
      dFF: 128,
      numLayers: 2,
      maxSeqLen: 64,
      eps: 1e-6,
      estimatedParams: 100000,
    },
    trainingConfig: {
      name: "tiny-test",
      label: "Tiny Test",
      description: "",
      version: 1 as const,
      model: "tiny",
      dataset: { dataset: "synthetic" as const, blockSize: 16, batchSize: 4 },
      optimizer: { type: "adamw", lr: 0.001 },
      scheduler: { type: "cosine" },
      epochs: 3,
      gradientAccumulation: 1,
      warmupSteps: 5,
      seed,
      gradientClipNorm: 1.0,
    },
    datasetConfig: {
      blockSize: 16,
      batchSize: 4,
      shuffle: true,
    },
    tokenizerConfig: {
      vocabSize: 1000,
      minFrequency: 1,
    },
    evaluationConfig: {
      generationPrompts: ["the cat", "once upon"],
      maxTokens: 20,
      temperature: 1.0,
    },
    seed,
  });
}

async function runTrainingWithSeed(seed: number): Promise<TrainingExecutionResult> {
  const experiment = makeExperiment(seed);
  const executor = createInlineTrainingExecutor(TINY_TRAINING_CORPUS);
  const bus = new TrainingEventBus();
  const runner = new ResearchExperimentRunner({ executor, eventBus: bus });

  const result = await runner.run(experiment, {
    saveToStore: false,
    runGenerationEval: false,
  });

  return result.training;
}

async function testRealTrainingProducesRealLoss(): Promise<TrainingExecutionResult> {
  const result = await runTrainingWithSeed(42);

  // Verify loss is REAL (not Math.random based)
  assertFinite(result.initialLoss, "initial loss should be finite (real)");
  assertFinite(result.finalLoss, "final loss should be finite (real)");
  assertFinite(result.bestLoss, "best loss should be finite (real)");
  assertGt(result.initialLoss, 0, "initial loss should be positive (real)");
  assertGt(result.finalLoss, 0, "final loss should be positive (real)");
  assertGt(result.totalSteps, 0, "total steps should be positive (real)");

  // Loss should change (model learns)
  assert(
    result.initialLoss !== result.finalLoss,
    "loss should change during training (model learns)"
  );

  // Verify loss is NOT a constant (would indicate fake data)
  assert(
    result.initialLoss > result.finalLoss,
    "initial loss should be higher than final loss (model improves)"
  );

  return result;
}

async function testEventBusReceivesRealStepEvents(): Promise<number> {
  const experiment = makeExperiment(42);
  const executor = createInlineTrainingExecutor(TINY_TRAINING_CORPUS);
  const bus = new TrainingEventBus();
  const runner = new ResearchExperimentRunner({ executor, eventBus: bus });

  let stepCount = 0;
  const stepLosses: number[] = [];

  bus.subscribe("training:step", (data) => {
    stepCount++;
    stepLosses.push(data.metrics.loss);
    assertFinite(data.metrics.loss, `step ${stepCount} loss should be finite`);
    assertGt(data.metrics.loss, 0, `step ${stepCount} loss should be positive`);
  });

  await runner.run(experiment, { saveToStore: false, runGenerationEval: false });

  assert(stepCount > 0, "should have received at least 1 step event");
  assert(stepLosses.length === stepCount, "should have tracked all losses");

  // Loss should generally decrease (with noise allowed)
  const firstFew = stepLosses.slice(0, Math.min(3, stepLosses.length));
  const lastFew = stepLosses.slice(-Math.min(3, stepLosses.length));
  const firstAvg = firstFew.reduce((a, b) => a + b, 0) / firstFew.length;
  const lastAvg = lastFew.reduce((a, b) => a + b, 0) / lastFew.length;

  if (stepCount >= 6) {
    // Generally, loss should decrease (last is lower than first)
    assert(
      lastAvg < firstAvg * 1.5,
      `overall loss should decrease: first avg=${firstAvg.toFixed(3)}, last avg=${lastAvg.toFixed(3)}`
    );
  }

  return stepCount;
}

async function testTrainingCompletes(): Promise<TrainingExecutionResult> {
  const experiment = makeExperiment(42);
  const executor = createInlineTrainingExecutor(TINY_TRAINING_CORPUS);
  const bus = new TrainingEventBus();
  const runner = new ResearchExperimentRunner({ executor, eventBus: bus });

  let completed = false;
  bus.once("training:complete", () => {
    completed = true;
  });

  const result = await runner.run(experiment, { saveToStore: false, runGenerationEval: false });

  assert(completed, "training:complete event should have fired");
  assertEqual(result.run.status, "completed" as const, "run should be completed");
  assertGt(result.training.durationMs, 0, "duration should be positive");

  console.log(`    Initial loss: ${result.training.initialLoss.toFixed(4)}`);
  console.log(`    Final loss:   ${result.training.finalLoss.toFixed(4)}`);
  console.log(`    Best loss:    ${result.training.bestLoss.toFixed(4)}`);
  console.log(`    Steps:        ${result.training.totalSteps}`);
  console.log(`    Duration:     ${result.training.durationMs}ms`);

  return result.training;
}

async function testNoMathRandomInMetrics(): Promise<void> {
  const experiment = makeExperiment(99);
  const executor = createInlineTrainingExecutor(TINY_TRAINING_CORPUS);
  const bus = new TrainingEventBus();
  const runner = new ResearchExperimentRunner({ executor, eventBus: bus });

  const stepLosses: number[] = [];

  bus.subscribe("training:step", (data) => {
    stepLosses.push(data.metrics.loss);
  });

  await runner.run(experiment, { saveToStore: false, runGenerationEval: false });

  // Verify all loss values are unique (not from a simple Math.random pattern)
  // If loss were Math.random based, every value would be completely random
  // Real loss should show a decreasing trend
  assert(stepLosses.length >= 2, "should have at least 2 loss values");

  // Check that the losses show pattern (real training has patterns, pure random does not)
  // At minimum, we verify no NaN or Infinity values
  for (const loss of stepLosses) {
    assertFinite(loss, "all losses should be finite");
    assertGt(loss, 0, "all losses should be positive");
  }
}

